INSERT INTO `questions` VALUES (37, '什么是贪心算法？它和动态规划有什么区别？', '请举一个适合用贪心算法解决的问题。', '算法工程师', 'Medium');
INSERT INTO `questions` VALUES (38, '二叉树的前序、中序、后序遍历分别是如何定义的？', '如果已知中序和后序遍历结果，如何重建这棵二叉树？', '算法工程师', 'Medium');
INSERT INTO `questions` VALUES (39, '什么是监督学习和无监督学习？请各举一例。', '半监督学习又是什么？', '人工智能工程师', 'Easy');
INSERT INTO `questions` VALUES (40, '在机器学习中，什么是过拟合和欠拟合？', '请列举至少三种防止过拟合的方法。', '人工智能工程师', 'Medium');
INSERT INTO `questions` VALUES (41, '请解释一下梯度下降算法的工作原理。', '随机梯度下降（SGD）、批量梯度下降（BGD）和小批量梯度下降（MBGD）有什么区别？', '人工智能工程师', 'Medium');
INSERT INTO `questions` VALUES (42, '你常用的激活函数有哪些？它们有什么优缺点？', '为什么ReLU比Sigmoid和Tanh在深度网络中更受欢迎？', '人工智能工程师', 'Medium');
INSERT INTO `questions` VALUES (43, '请解释一下卷积神经网络（CNN）的核心思想。', '卷积层和池化层的作用分别是什么？', '人工智能工程师', 'Medium');
INSERT INTO `questions` VALUES (44, '循环神经网络（RNN）为什么能处理序列数据？', 'RNN存在什么问题？LSTM和GRU是如何解决这些问题的？', '人工智能工程师', 'Medium');
INSERT INTO `questions` VALUES (45, '请解释一下什么是偏差（Bias）和方差（Variance）的权衡。', '一个好的模型应该有高偏差还是低偏差？高方差还是低方差？', '人工智能工程师', 'Medium');
INSERT INTO `questions` VALUES (46, '请解释一下Transformer模型中的自注意力机制（Self-Attention）。', '相比于RNN，Transformer在处理长序列时有什么优势？', '人工智能工程师', 'Hard');
INSERT INTO `questions` VALUES (47, '反向传播算法（Backpropagation）的原理是什么？', '请简述其计算过程。', '人工智能工程师', 'Hard');
INSERT INTO `questions` VALUES (48, 'L1和L2正则化有什么区别？它们是如何防止过拟合的？', '哪种正则化更容易产生稀疏解（即让一些权重变为0）？为什么？', '人工智能工程师', 'Hard');
INSERT INTO `questions` VALUES (49, '如何评估一个分类模型的性能？', '请解释准确率（Accuracy）、精确率（Precision）、召回率（Recall）和F1-Score。', '人工智能工程师', 'Medium');
INSERT INTO `questions` VALUES (50, 'TensorFlow和PyTorch你更熟悉哪个？谈谈它们之间的主要区别。', '请从动态图与静态图、易用性、社区生态等方面进行比较。', '人工智能工程师', 'Medium');
INSERT INTO `questions` VALUES (51, '什么是词嵌入（Word Embedding）？', 'Word2Vec和GloVe这两种方法有什么不同？', '人工智能工程师', 'Hard');
INSERT INTO `questions` VALUES (52, '请解释一下软件测试中的黑盒测试和白盒测试。', '灰盒测试又是什么？', '测试工程师', 'Easy');
INSERT INTO `questions` VALUES (53, '请描述一下Bug的生命周期。', '一个Bug从被发现到被关闭通常会经历哪些状态？', '测试工程师', 'Easy');
INSERT INTO `questions` VALUES (54, '什么是测试金字塔（Test Pyramid）模型？', '它对我们的测试策略有什么指导意义？', '测试工程师', 'Medium');
INSERT INTO `questions` VALUES (55, '单元测试、集成测试和端到端（E2E）测试有什么区别？', '在一个项目中，这三类测试的比例应该是怎样的？', '测试工程师', 'Medium');
INSERT INTO `questions` VALUES (56, '请设计一个登录页面的测试用例。', '请从功能、UI、性能、安全、兼容性等多个方面考虑。', '测试工程师', 'Medium');
INSERT INTO `questions` VALUES (57, '什么是性能测试、负载测试和压力测试？', '这三者之间有什么关联和区别？', '测试工程师', 'Medium');
INSERT INTO `questions` VALUES (58, '在做API接口测试时，你主要关注哪些方面？', '你会使用哪些工具来进行接口测试？', '测试工程师', 'Medium');
INSERT INTO `questions` VALUES (59, '你如何在一个敏捷开发团队中开展测试工作？', '测试人员应该在敏捷开发的哪个阶段介入？', '测试工程师', 'Medium');
INSERT INTO `questions` VALUES (60, '请解释一下Selenium WebDriver的工作原理。', '你如何处理页面元素的动态加载和等待问题？', '测试工程师', 'Hard');
INSERT INTO `questions` VALUES (61, '什么是契约测试（Contract Testing）？', '它在微服务架构的测试中有什么作用？', '测试工程师', 'Hard');
INSERT INTO `questions` VALUES (62, '你如何设计一个复杂业务系统的测试策略？', '比如一个电商平台的下单流程。', '测试工程师', 'Hard');
INSERT INTO `questions` VALUES (63, '什么是回归测试？自动化回归测试的价值是什么？', '在什么时机执行回归测试比较合适？', '测试工程师', 'Easy');
INSERT INTO `questions` VALUES (64, '什么是大数据？它有哪些典型特征（3V或5V）？', '请分别解释Volume, Velocity, Variety。', '大数据工程师', 'Easy');
INSERT INTO `questions` VALUES (65, '请简述HDFS的架构和读写数据的流程。', 'NameNode和DataNode的作用分别是什么？', '大数据工程师', 'Medium');
INSERT INTO `questions` VALUES (66, 'Apache Spark与Hadoop MapReduce相比有哪些优势？', '为什么Spark的计算速度通常更快？', '大数据工程师', 'Medium');
INSERT INTO `questions` VALUES (67, '请解释Spark中的RDD、DataFrame和Dataset的区别。', '在开发中你倾向于使用哪个？为什么？', '大数据工程师', 'Medium');
INSERT INTO `questions` VALUES (68, '在Spark中，什么是数据倾斜？你是如何发现并解决数据倾斜问题的？', '请列举几种处理数据倾斜的方法。', '大数据工程师', 'Hard');
INSERT INTO `questions` VALUES (69, '请解释Kafka的架构及其核心组件。', 'Producer, Consumer, Broker, Topic, Partition分别是什么？', '大数据工程师', 'Medium');
INSERT INTO `questions` VALUES (70, '什么是数据仓库中的维度建模？', '事实表和维度表是什么？星型模型和雪花模型有什么区别？', '大数据工程师', 'Medium');
INSERT INTO `questions` VALUES (71, 'Lambda架构和Kappa架构有什么区别？', '它们分别适用于什么样的数据处理场景？', '大数据工程师', 'Hard');
INSERT INTO `questions` VALUES (72, '请解释OLTP和OLAP系统的区别。', '它们在设计目标、数据特点和典型应用上有什么不同？', '大数据工程师', 'Medium');
INSERT INTO `questions` VALUES (73, '常用的列式存储文件格式有哪些？', '与行式存储（如CSV）相比，列式存储（如Parquet, ORC）有什么优势？', '大数据工程师', 'Hard');
INSERT INTO `questions` VALUES (74, '如何保障流处理系统的数据一致性？', '请解释At-least-once, At-most-once, 和 Exactly-once语义。', '大数据工程师', 'Hard');
INSERT INTO `questions` VALUES (75, 'ZooKeeper在分布式系统中扮演什么角色？', '请列举它的一些典型应用场景。', '大数据工程师', 'Hard');
INSERT INTO `questions` VALUES (76, '什么是DevOps？它解决了什么问题？', '请解释一下DevOps的核心理念CAMS（Culture, Automation, Measurement, Sharing）。', '运维工程师', 'Easy');
INSERT INTO `questions` VALUES (77, 'Docker与传统虚拟机（VM）相比有什么优势和劣势？', '请从资源隔离、启动速度、镜像大小等方面进行比较。', '运维工程师', 'Easy');
INSERT INTO `questions` VALUES (78, '请描述一个典型的CI/CD流水线包含哪些阶段。', '你使用过哪些CI/CD工具？', '运维工程师', 'Medium');
INSERT INTO `questions` VALUES (79, '请简述Kubernetes的核心架构。', 'Master节点和Worker节点分别包含哪些核心组件？', '运维工程师', 'Medium');
INSERT INTO `questions` VALUES (80, '什么是基础设施即代码（Infrastructure as Code, IaC）？', 'Terraform和Ansible有什么区别和联系？', '运维工程师', 'Medium');
INSERT INTO `questions` VALUES (81, '什么是蓝绿部署、金丝雀发布（灰度发布）和滚动发布？', '请说明它们各自的优缺点和适用场景。', '运维工程师', 'Medium');
INSERT INTO `questions` VALUES (82, '当你在Kubernetes中发现一个Pod的状态是`CrashLoopBackOff`时，你会如何排查问题？', '请列出你的排查步骤。', '运维工程师', 'Hard');
INSERT INTO `questions` VALUES (83, '什么是服务网格（Service Mesh）？它解决了什么问题？', 'Istio和Linkerd是用来做什么的？', '运维工程师', 'Hard');
INSERT INTO `questions` VALUES (84, '你如何设计一套监控告警系统？', '请解释白盒监控和黑盒监控。Prometheus的监控原理是什么？', '运维工程师', 'Hard');
INSERT INTO `questions` VALUES (85, '请解释一下Linux系统的Load Average。', 'Load Average的三个数值（1分钟、5分钟、15分钟）分别代表什么？数值多高时需要引起关注？', '运维工程师', 'Medium');
INSERT INTO `questions` VALUES (86, 'Nginx可以用来做什么？', '请解释一下它作为反向代理和负载均衡器时的配置示例。', '运维工程师', 'Medium');
INSERT INTO `questions` VALUES (87, '如何保障服务器的安全性？', '请从网络、系统、应用等层面列举一些常用的安全加固措施。', '运维工程师', 'Hard');
INSERT INTO `questions` VALUES (88, '请解释一下RAID的不同级别（如RAID 0, 1, 5, 10）。', '它们在冗余性、性能和成本方面有何不同？', '运维工程师', 'Hard');
INSERT INTO `questions` VALUES (89, '作为一名产品经理，你如何进行需求优先级排序？', '请介绍一下你常用的优先级框架，例如RICE或MoSCoW。', '产品经理', 'Medium');
INSERT INTO `questions` VALUES (90, '什么是MVP（最小可行产品）？', '它和原型（Prototype）有什么区别？构建MVP的目的是什么？', '产品经理', 'Easy');
INSERT INTO `questions` VALUES (91, '请描述一下你理解的产品开发流程。', '从需求发现到产品上线，主要包含哪些环节？', '产品经理', 'Medium');
INSERT INTO `questions` VALUES (92, '你如何进行用户研究和竞品分析？', '你会通过哪些渠道收集用户反馈和竞品信息？', '产品经理', 'Medium');
INSERT INTO `questions` VALUES (93, '什么是用户画像（Persona）和用户旅程图（User Journey Map）？', '这两个工具在产品设计中有什么作用？', '产品经理', 'Medium');
INSERT INTO `questions` VALUES (94, '你会关注哪些核心数据指标来衡量产品的成功？', '请解释一下AARRR模型或HEART框架。', '产品经理', 'Medium');
INSERT INTO `questions` VALUES (95, '当你和开发团队在某个功能实现方案上产生分歧时，你会如何处理？', '请描述你的沟通和决策过程。', '产品经理', 'Medium');
INSERT INTO `questions` VALUES (96, '如何判断产品是否达到了“产品-市场契合”（Product-Market Fit）的状态？', '你会观察哪些定性和定量的指标？', '产品经理', 'Hard');
INSERT INTO `questions` VALUES (97, '请为一款你熟悉的应用设计一个新功能。', '请说明这个功能要解决的用户痛点、核心流程和预期的商业价值。', '产品经理', 'Hard');
INSERT INTO `questions` VALUES (98, '你如何制定一个产品的路线图（Roadmap）？', 'Roadmap应该包含哪些关键信息？它的受众是谁？', '产品经理', 'Hard');
INSERT INTO `questions` VALUES (99, '假设你负责的产品的日活跃用户数（DAU）在过去一周下降了20%，你会如何分析原因？', '请列出你的分析思路和步骤。', '产品经理', 'Hard');
INSERT INTO `questions` VALUES (100, 'UI和UX的区别是什么？', '为什么说产品经理需要具备良好的用户体验（UX）意识？', '产品经理', 'Easy');

